const TIP_KEYS = ["chat.tips.agent.1", "chat.tips.agent.2", "chat.tips.agent.3", "chat.tips.agent.4", "chat.tips.input.2", "chat.tips.input.3", "chat.tips.asset.5", "chat.tips.system.1", "chat.tips.system.3", "chat.tips.system.5", "chat.tips.system.6", "chat.tips.discovery.1", "chat.tips.discovery.4", "chat.tips.discovery.5", "chat.tips.discovery.8", "chat.tips.discovery.9", "chat.tips.discovery.10", "chat.tips.discovery.11", "chat.tips.skill.1", "chat.tips.skill.3", "chat.tips.skill.4", "chat.tips.plugin.1", "chat.tips.assetCenter.1", "chat.tips.assetCenter.3"];
const IM_BRIDGE_TIP_KEY = "chat.tips.system.5";
function availableTipKeys() {
  if (getRuntimeConfig().region === "overseas") {
    return TIP_KEYS.filter(key2 => key2 !== IM_BRIDGE_TIP_KEY);
  }
  return TIP_KEYS;
}
function shuffleArray(arr) {
  const copy2 = [...arr];
  for (let i2 = copy2.length - 1; i2 > 0; i2--) {
    const j2 = Math.floor(Math.random() * (i2 + 1));
    [copy2[i2], copy2[j2]] = [copy2[j2], copy2[i2]];
  }
  return copy2;
}
function localizeShortcuts(text2) {
  if (IS_MAC) return text2;
  return text2.replace(/⌘⇧/g, "Ctrl+Shift+").replace(/⌘/g, "Ctrl+").replace(/⇧/g, "Shift+").replace(/⌥/g, "Alt+").replace(/Cmd\+Shift\+/g, "Ctrl+Shift+").replace(/Cmd\+/g, "Ctrl+").replace(/Option\+/g, "Alt+");
}
function useChatTips(active2) {
  const {
    t: t2
  } = useTranslation();
  const poolRef = reactExports.useRef(shuffleArray(availableTipKeys()));
  const indexRef = reactExports.useRef(0);
  const [currentKey, setCurrentKey] = reactExports.useState(null);
  reactExports.useEffect(() => {
    const advance = () => {
      setCurrentKey(poolRef.current[indexRef.current]);
      indexRef.current += 1;
      if (indexRef.current >= poolRef.current.length) {
        poolRef.current = shuffleArray(availableTipKeys());
        indexRef.current = 0;
      }
    };
    advance();
    const timer2 = setInterval(advance, ROTATION_INTERVAL_MS);
    return () => clearInterval(timer2);
  }, [active2]);
  if (!currentKey) return null;
  return localizeShortcuts(t2(currentKey));
}
let _seq = 0;
function id() {
  return `mock_media_gen_${++_seq}`;
}
const PREFIX = "hub_";
function tool(name2, args, result, status = "ok") {
  const fullName = `${PREFIX}${name2}`;
  return {
    id: id(),
    role: "agent",
    type: "tool",
    content: fullName,
    toolName: fullName,
    toolStatus: status,
    toolArgs: JSON.stringify(args),
    toolResult: JSON.stringify(result)
  };
}
function running(name2, args) {
  const fullName = `${PREFIX}${name2}`;
  return {
    id: id(),
    role: "agent",
    type: "tool",
    content: fullName,
    toolName: fullName,
    toolStatus: "running",
    toolArgs: JSON.stringify(args)
  };
}
